@php $title=(string)data_get($item,'title','Sản phẩm');$image=(string)data_get($item,'image',data_get($item,'image_url','/theme-demo/ec903/food-source.png'));$url=(string)data_get($item,'url','#');$price=(float)data_get($item,'price',0);$original=(float)data_get($item,'original_price',0); @endphp<article class="f407-product" data-f407-reveal><a href="{{ $url }}"><img src="{{ $image }}" alt="{{ data_get($item,'alt',$title) }}"></a><div><h3><a href="{{ $url }}">{{ $title }}</a></h3><p>@if($price>0)<strong>{{ number_format($price,0,',','.') }}đ</strong>@else<strong>Liên hệ</strong>@endif @if($original>$price)<del>{{ number_format($original,0,',','.') }}đ</del>@endif</p><span>★★★★★</span></div></article>
